# regenerate exact-two
code='''def transform(grid):
    sep = next(v for v in set(grid[0]) if sum(x == v for x in grid[0]) > 1 and v != max(set(grid[0]), key=grid[0].count))
    # separator rows/columns are the full-length lines; derive interior values and groups
    row_groups=[]; start=0
    for r,row in enumerate(grid):
        if all(x==sep for x in row):
            if r>start: row_groups.append((start,r))
            start=r+1
    if start<len(grid): row_groups.append((start,len(grid)))
    col_groups=[]; start=0
    for c in range(len(grid[0])):
        if all(row[c]==sep for row in grid):
            if c>start: col_groups.append((start,c))
            start=c+1
    if start<len(grid[0]): col_groups.append((start,len(grid[0])))
    bg=next(x for x in grid[0] if x!=sep and x!=max(set(grid[0]),key=grid[0].count))
    mark=1
    return [[mark if sum(grid[r][c]!=bg and grid[r][c]!=sep for r in range(a,b) for c in range(x,y))==2 else bg for x,y in col_groups] for a,b in row_groups]
'''
